+// Chooses the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+function headerValue(headers, name) {
+  for (const [k, v] of Object.entries(headers ?? {})) {
+    if (k.toLowerCase() === name) return Array.isArray(v) ? v.join(",") : v;
+  }
+  return undefined;
+}
+
+/** The supported language the Accept-Language header prefers (q-values, region tags), else `fallback`. */
+export function requestLanguage(headers, fallback) {
+  const header = headerValue(headers, "accept-language");
+  if (typeof header !== "string") return fallback;
+  const weights = new Map();
+  let wildcard = null;
+  for (const part of header.split(",")) {
+    const [range, ...attrs] = part.split(";").map((s) => s.trim());
+    if (!range) continue;
+    let q = 1;
+    let valid = true;
+    for (const attr of attrs) {
+      const m = /^q\s*=\s*(.*)$/i.exec(attr);
+      if (!m) continue;
+      if (/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1])) q = Number(m[1]);
+      else valid = false;
+    }
+    if (!valid) continue;
+    if (range === "*") {
+      wildcard = Math.max(wildcard ?? 0, q);
+      continue;
+    }
+    const lang = range.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    // An exact tag ("ko") says more about the language than a regional one ("ko-KR").
+    const exact = !range.includes("-");
+    const seen = weights.get(lang);
+    if (!seen || (exact && !seen.exact) || (exact === seen.exact && q > seen.q)) weights.set(lang, { q, exact });
+  }
+  let best = null;
+  let bestQ = 0;
+  for (const lang of LANGUAGES) {
+    const q = weights.has(lang) ? weights.get(lang).q : (wildcard ?? 0);
+    if (q > bestQ || (q > 0 && q === bestQ && lang === fallback)) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
